#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "trmm.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// A is M x M, we model it with dimensions 'k' (row) and 'i' (column)
	DEFINE_PROTO_STRUCT(a_layout, i_vec ^ k_vec);
	// B is M x N, we model it with dimensions 'i' (row) and 'j' (column)
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ i_vec);
} tuning;

// initialization function
// A: k x i  (M x M)
// B: i x j  (M x N)
void init_array(num_t &alpha, auto A, auto B) {
	using namespace noarr;

	alpha = (num_t)1.5;

	const std::size_t m = A | get_length<'k'>(); // size of A in both dimensions
	const std::size_t n = B | get_length<'j'>(); // number of columns of B

	// Initialize A as a unit lower-triangular matrix:
	// A[row][col] = (row+col)%m / m for col < row
	// A[row][row] = 1
	// A[row][col] = 0 for col > row (not used in the kernel, but defined here)
	traverser(A).for_each([=](auto state) {
		auto row = get_index<'k'>(state);
		auto col = get_index<'i'>(state);

		if (col < row)
			A[state] = (num_t)((row + col) % m) / (num_t)m;
		else if (col == row)
			A[state] = (num_t)1.0;
		else
			A[state] = (num_t)0.0;
	});

	// Initialize B:
	// B[i][j] = (n + (i - j)) % n / n
	traverser(B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		B[state] = (num_t)((n + (i - j)) % n) / (num_t)n;
	});
}

// computation kernel
// Form B := alpha * A^T * B
// A: k x i  (M x M, triangular)
// B: i x j  (M x N)
[[gnu::flatten, gnu::noinline]]
void kernel_trmm(num_t alpha, auto A, auto B) {
	using namespace noarr;

	// Views:
	//  - A_ki: A with dimensions 'k' (row), 'i' (column) as modeled above
	//  - B_i : B with dimensions 'i' (row), 'j' (column)
	//  - B_k : a view of B where the row dimension is renamed to 'k'
	auto A_ki = A;
	auto B_i = B;
	auto B_k = B ^ noarr::rename<'i', 'k'>(); // dims: 'k', 'j'

	#pragma scop
	// First accumulate the contributions:
	// for i in 0..M-1
	//   for k in i+1..M-1
	//     for j in 0..N-1
	//       B[i][j] += A[k][i] * B[k][j];
	noarr::traverser(A_ki, B_i, B_k).template for_dims<'i', 'k'>([=](auto ik_trav) {
		auto ik_state = ik_trav.state();
		auto i = noarr::get_index<'i'>(ik_state);
		auto k = noarr::get_index<'k'>(ik_state);

		// Only use strictly lower-triangular part: k > i
		if (k <= i)
			return;

		// Iterate over all columns j for this (i, k) pair
		ik_trav.for_each([=](auto state) {
			// state has dimensions 'i', 'k', 'j'
			// A_ki[state] -> A[k][i]
			// B_i[state]  -> B[i][j]
			// B_k[state]  -> B[k][j]
			B_i[state] += A_ki[state] * B_k[state];
		});
	});

	// Then scale B by alpha:
	// for all i, j: B[i][j] = alpha * B[i][j];
	noarr::traverser(B_i).for_each([=](auto state) {
		B_i[state] *= alpha;
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// input data
	num_t alpha;

	// set logical lengths for all dimensions
	auto set_lengths =
		noarr::set_length<'i'>(m) ^
		noarr::set_length<'j'>(n) ^
		noarr::set_length<'k'>(m);

	// allocate bags
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(alpha, A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_trmm(alpha, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (for verification)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, B.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}

