#include <iostream>
#include <string>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "trmm.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// A: k x i (M x M)
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
	// B: i x j (M x N)
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ i_vec);
} tuning;

// initialization function
void init_array(num_t &alpha, auto A, auto B) {
	using namespace noarr;

	alpha = (num_t)1.5;

	// A: unit lower-triangular MxM
	// A[k][i] for i < k: (k + i) % M / M
	traverser(A).template for_dims<'k'>([=](auto trav_k) {
		auto state_k = trav_k.state();
		std::size_t k = get_index<'k'>(state_k);
		std::size_t m_len = A | get_length<'k'>();

		// strictly lower triangular part in row k (i = 0 .. k-1)
		auto lower = trav_k.order(slice<'i'>(0, k));
		lower.for_each([=](auto state) {
			auto [kk, ii] = get_indices<'k', 'i'>(state);
			A[state] = (num_t)((kk + ii) % m_len) / (num_t)m_len;
		});

		// diagonal element A[k][k] = 1.0
		A.template at<'k', 'i'>(k, k) = (num_t)1.0;
	});

	// B: B[i][j] = (n + (i - j)) % n / n
	traverser(B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		std::size_t n_len = B | get_length<'j'>();

		// compute with signed arithmetic to match original C semantics
		long long n_ll = static_cast<long long>(n_len);
		long long i_ll = static_cast<long long>(i);
		long long j_ll = static_cast<long long>(j);
		long long tmp = n_ll + (i_ll - j_ll); // guaranteed >= 1
		long long mod = tmp % n_ll;

		B[state] = (num_t)mod / (num_t)n_len;
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_trmm(num_t alpha, auto A, auto B) {
	using namespace noarr;

	// View of B where the row dimension is named 'k' instead of 'i'
	auto B_k = B ^ rename<'i', 'k'>();

	// BLAS parameters
	// SIDE   = 'L'
	// UPLO   = 'L'
	// TRANSA = 'T'
	// DIAG   = 'U'
	// => Form  B := alpha * A^T * B
	// A is MxM, B is MxN
#pragma scop
	traverser(A, B, B_k).template for_dims<'i'>([=](auto trav_i) {
		trav_i.template for_dims<'j'>([=](auto trav_ij) {
			auto state_ij = trav_ij.state();
			std::size_t i_idx = get_index<'i'>(state_ij);
			std::size_t m_len = A | get_length<'k'>();

			// k runs from i+1 to M-1
			std::size_t start_k = i_idx + 1;
			std::size_t len_k = (start_k < m_len) ? (m_len - start_k) : 0;

			auto trav_ijk = trav_ij.order(slice<'k'>(start_k, len_k));

			trav_ijk.for_each([=](auto state) {
				// state has dimensions 'i', 'j', 'k'
				// B[i][j] += A[k][i] * B[k][j];
				B[state] += A[state] * B_k[state];
			});

			// B[i][j] = alpha * B[i][j];
			B[state_ij] = alpha * B[state_ij];
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// scalar parameter
	num_t alpha;

	// set lengths for all dimensions
	auto set_lengths =
		noarr::set_length<'i'>(m) ^
		noarr::set_length<'j'>(n) ^
		noarr::set_length<'k'>(m);

	// allocate bags
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(alpha, A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_trmm(alpha, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, B.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}

#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "trmm.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// A is M x M, we view it as: rows = 'k', cols = 'i'
	DEFINE_PROTO_STRUCT(a_layout, i_vec ^ k_vec);

	// B is M x N, we view it as: rows = 'i', cols = 'j'
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ i_vec);
} tuning;

// initialization function
// A: k x i  (M x M, unit lower triangular)
// B: i x j  (M x N)
void init_array(num_t &alpha, auto A, auto B) {
	using namespace noarr;

	alpha = (num_t)1.5;

	// retrieve problem sizes from the structures
	int m = static_cast<int>(A | get_length<'k'>()); // A is M x M: length in 'k' (rows) is M
	int n = static_cast<int>(B | get_length<'j'>()); // B is M x N: length in 'j' (cols) is N

	// Initialize A as unit lower-triangular:
	// for (row = 0..m-1)
	//   for (col = 0..row-1) A[row][col] = (row + col) % m / m
	//   A[row][row] = 1.0
	//   for (col > row) A[row][col] = 0.0
	traverser(A).for_each([=](auto state) {
		int k = static_cast<int>(get_index<'k'>(state)); // row index
		int i = static_cast<int>(get_index<'i'>(state)); // column index

		if (i < k) {
			A[state] = (num_t)((k + i) % m) / (num_t)m;
		} else if (i == k) {
			A[state] = (num_t)1.0;
		} else {
			A[state] = (num_t)0.0;
		}
	});

	// Initialize B:
	// for (i = 0..m-1)
	//   for (j = 0..n-1)
	//     B[i][j] = ((n + (i - j)) % n) / n
	traverser(B).for_each([=](auto state) {
		int i = static_cast<int>(get_index<'i'>(state));
		int j = static_cast<int>(get_index<'j'>(state));

		B[state] = (num_t)((n + (i - j)) % n) / (num_t)n;
	});
}

// computation kernel
// BLAS parameters:
// SIDE   = 'L'
// UPLO   = 'L'
// TRANSA = 'T'
// DIAG   = 'U'
// => Form  B := alpha * A^T * B.
// A is M x M (unit lower triangular)
// B is M x N
[[gnu::flatten, gnu::noinline]]
void kernel_trmm(num_t alpha, auto A, auto B) {
	using namespace noarr;

	#pragma scop

	// First phase: accumulate B[i][j] += A[k][i] * B[k][j] for k > i
	// We implement this as:
	// for i in [0, M)
	//   for j in [0, N)
	//     for k in [0, M)
	//       if (k > i) B[i][j] += A[k][i] * B[k][j];
	// This is equivalent to the original loop with k from i+1 to M-1.
	traverser(A, B).template for_dims<'i'>([=](auto trav_i) {
		// i is fixed here
		trav_i.template for_dims<'j'>([=](auto trav_ij) {
			// i and j are fixed here, only k varies
			trav_ij.for_each([=](auto state) {
				auto i = get_index<'i'>(state);
				auto k = get_index<'k'>(state);

				if (k > i) {
					// current (i, j) position in B
					auto i_idx = i;
					auto j_idx = get_index<'j'>(state);

					// states for accesses:
					// B[i][j]
					auto state_ij = noarr::idx<'i', 'j'>(i_idx, j_idx);
					// B[k][j]
					auto state_kj = noarr::idx<'i', 'j'>(k, j_idx);
					// A[k][i]
					auto state_ki = noarr::idx<'k', 'i'>(k, i_idx);

					B[state_ij] += A[state_ki] * B[state_kj];
				}
			});
		});
	});

	// Second phase: scale B by alpha
	// for (i = 0..M-1)
	//   for (j = 0..N-1)
	//     B[i][j] = alpha * B[i][j];
	traverser(B).for_each([=](auto state) {
		B[state] *= alpha;
	});

	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// input data
	num_t alpha;

	// Common length descriptor for all dimensions we use:
	// 'i' - row index of B and column index of A
	// 'j' - column index of B
	// 'k' - row index of A
	auto set_lengths =
		noarr::set_length<'i'>(m) ^
		noarr::set_length<'j'>(n) ^
		noarr::set_length<'k'>(m);

	// Allocate bags for A and B with the chosen layouts
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(alpha, A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_trmm(alpha, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (dump B) if requested
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, B.get_ref() ^ noarr::hoist<'i'>());
	}

	// print time
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}

#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "trmm.hpp"

using num_t = DATA_TYPE;

namespace {

// basic 1D vectors for dimensions
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

// layout tuning (memory layout) for the matrices
struct tuning {
	// A is M x M, indexed by (i, k), k is the inner (contiguous) dimension
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
	// B is M x N, indexed by (i, j), j is the inner (contiguous) dimension
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ i_vec);
} tuning;

// Array initialization
// A : i x k  (M x M)
// B : i x j  (M x N)
void init_array(num_t &alpha, auto A, auto B) {
	using namespace noarr;

	// set scalar
	alpha = (num_t)1.5;

	// retrieve lengths from the structures
	auto m_len = A | get_length<'i'>();
	auto n_len = B | get_length<'j'>();

	// Initialize A as unit lower triangular:
	// for i in [0, m)
	//   for j in [0, i)   A[i][j] = ((i + j) % m) / m;
	//   A[i][i] = 1.0;
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);

		if (k < i) {
			A[state] = (num_t)((i + k) % m_len) / (num_t)m_len;
		} else if (k == i) {
			A[state] = (num_t)1.0;
		}
		// Elements with k > i remain uninitialized, as in the original C code.
	});

	// Initialize B:
	// for i in [0, m)
	//   for j in [0, n)   B[i][j] = ((n + (i - j)) % n) / n;
	traverser(B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		int ii = static_cast<int>(i);
		int jj = static_cast<int>(j);
		int nn = static_cast<int>(n_len);

		int val = (nn + (ii - jj)) % nn;
		B[state] = (num_t)val / (num_t)n_len;
	});
}

// Main computational kernel
// A : i x k  (M x M)
// B : i x j  (M x N)
// BLAS parameters:
// SIDE   = 'L'
// UPLO   = 'L'
// TRANSA = 'T'
// DIAG   = 'U'
// => Form  B := alpha * A**T * B.
[[gnu::flatten, gnu::noinline]]
void kernel_trmm(num_t alpha, auto A, auto B) {
	using namespace noarr;

	auto m_len = B | get_length<'i'>(); // M

#pragma scop
	// Outer loop over i
	traverser(B).template for_dims<'i'>([=](auto inner) {
		// Inner loop over j for this fixed i
		inner.template for_each<'j'>([=](auto state) {
			auto i_idx = get_index<'i'>(state);
			auto j_idx = get_index<'j'>(state);

			// Original C:
			// for (k = i+1; k < M; k++)
			//   B[i][j] += A[k][i] * B[k][j];
			for (std::size_t k = i_idx + 1; k < m_len; ++k) {
				// A[k][i]  -> dim 'i' = k, dim 'k' = i
				auto a_state = noarr::idx<'i', 'k'>(k, i_idx);
				// B[k][j]  -> dim 'i' = k, dim 'j' = j_idx
				auto b_state = noarr::idx<'i', 'j'>(k, j_idx);

				B[state] += A[a_state] * B[b_state];
			}

			// B[i][j] = alpha * B[i][j];
			B[state] = alpha * B[state];
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t m = M;
	std::size_t n = N;

	// Scalar parameter
	num_t alpha;

	// Set lengths for structures
	auto set_lengths_A = noarr::set_length<'i'>(m) ^ noarr::set_length<'k'>(m);
	auto set_lengths_B = noarr::set_length<'i'>(m) ^ noarr::set_length<'j'>(n);

	// Allocate bags (data + structure)
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths_A);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths_B);

	// Initialize arrays
	init_array(alpha, A.get_ref(), B.get_ref());

	// Start timer
	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_trmm(alpha, A.get_ref(), B.get_ref());

	// Stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, B.get_ref() ^ noarr::hoist<'i'>());
	}

	// Print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
